{
  "headline": "Prioritize indoor air and N95 masks for senior and cardiac members",
  "summary": "Air quality is currently {{level.name}} with an AQI of {{aqi.now}}. Focus on indoor filtration and protective measures for vulnerable members. The best outdoor air window is from {{best.start}} to {{best.end}}.",
  "cards": [
    {
      "actionId": "run_purifier_through_night",
      "title": "Run air purifiers continuously",
      "why": "Continuous mechanical filtration significantly reduces indoor PM2.5 exposure by up to {{impact.run_purifier_through_night.pct}}.",
      "when": "Run throughout the night and when members are home.",
      "steps": [
        "Ensure purifiers are placed in main living areas and bedrooms.",
        "Keep doors closed to concentrate filtration in occupied rooms."
      ]
    },
    {
      "actionId": "exercise_indoors_when_poor",
      "title": "Move exercise indoors",
      "why": "Reduces exposure during high pollution periods, offering {{impact.exercise_indoors_when_poor.pct}} lower exposure.",
      "when": "When air quality is {{level.name}} or worse.",
      "steps": [
        "Engage in low-impact indoor activities like yoga or stretching.",
        "Ensure good ventilation in the exercise space if possible."
      ]
    },
    {
      "actionId": "n95_for_open_transport",
      "title": "Use N95 masks for any open transport",
      "why": "Provides crucial protection, reducing exposure by {{impact.n95_for_open_transport.pct}} during commutes.",
      "when": "For any travel on public transport or in shared vehicles.",
      "steps": [
        "Ensure a snug fit for maximum effectiveness.",
        "Wear the mask during the entire journey, including waiting times."
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Use damp mopping instead of dry sweeping",
      "why": "Prevents stirring up settled dust and particulate matter, improving indoor air quality.",
      "when": "For all regular floor cleaning.",
      "steps": [
        "Use a damp cloth or mop.",
        "Avoid sweeping, especially in high-traffic areas."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for no burning in the community",
      "why": "Community-wide efforts can lead to significant reductions in local pollution.",
      "when": "During community meetings or discussions.",
      "steps": [
        "Raise awareness about the health impacts of burning.",
        "Encourage alternative waste disposal methods."
      ]
    },
    {
      "actionId": "share_community_brief",
      "title": "Share the Community Brief",
      "why": "Informing your community can encourage collective action on air quality.",
      "when": "Share with neighbors and local authorities.",
      "steps": [
        "Distribute the brief to your Resident Welfare Association (RWA).",
        "Discuss potential community-level interventions."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "senior",
      "note": "Limit outdoor exposure, especially during high pollution hours. Ensure consistent use of N95 masks when venturing out."
    },
    {
      "group": "cardiac",
      "note": "Avoid strenuous physical activity outdoors. Monitor symptoms closely and keep medication accessible."
    }
  ],
  "tradeoffs": [
    "Using N95 masks on open transport is essential to mitigate increased exposure."
  ]
}
